with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '唐獅子図屏風', '狩野永徳', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Kano_Eitoku_002.jpg/960px-Kano_Eitoku_002.jpg', '桃山時代を代表する絵師、狩野永徳の作と伝わる屏風です。金地を背に、2頭の唐獅子がたてがみをなびかせて堂々と歩む姿を、太く力強い線で大きく描いています。高さ約2.2メートル、幅約4.5メートルという屏風としては異例の大きさで、画面の端が切られた跡から、もとはさらに大きかったと考えられています。豊臣秀吉が毛利輝元に贈ったという言い伝えがあり、明治時代に毛利家から皇室へ献上され、現在は皇居三の丸尚蔵館が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Kano_Eitoku_002.jpg'),
    (2, '大使たち', 'ハンス・ホルバイン（子）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Hans_Holbein_the_Younger_-_The_Ambassadors_-_Google_Art_Project.jpg/960px-Hans_Holbein_the_Younger_-_The_Ambassadors_-_Google_Art_Project.jpg', '1533年、イングランド王ヘンリー8世の宮廷で活躍したホルバインが描いた二重肖像画です。左はフランス大使ジャン・ド・ダントヴィル、右はラヴォールの司教ジョルジュ・ド・セルヴ。二人の間の棚には天球儀や地球儀、日時計などの観測器具、弦の切れたリュートや賛美歌集が並び、当時の学問や宗教の対立を映すと読まれてきました。床の上の奇妙な形は、斜めから見ると頭蓋骨に見えるだまし絵で、栄華の中に死を思い出させる仕掛けです。ロンドンのナショナル・ギャラリー所蔵。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Hans_Holbein_the_Younger_-_The_Ambassadors_-_Google_Art_Project.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('皇居三の丸尚蔵館、11月3日グランドオープン', '全面開館記念の特別展「皇室の至宝―美いづるところ」を開催。正倉院宝物を皇居内で初公開。', '皇居三の丸尚蔵館のグランドオープンを記念する特別展「皇室の至宝―美いづるところ」が、2026年11月3日から2027年1月24日まで開催される。作品は前期・中期・後期で全面的に入れ替わる。前期には正倉院宝物の《螺鈿紫檀琵琶》などが並び、聖武天皇ゆかりの宝物を皇居内で公開するのは今回が初めてとなる。伊藤若冲や狩野探幽らの江戸絵画も展示される。中期は国宝《竜首水瓶》など法隆寺献納宝物の代表作と大正美術、後期は国宝《蒙古襲来絵詞》や狩野永徳《唐獅子図屏風》に加え、昭和改元100年にちなむ昭和美術を紹介する。観覧は日時指定予約制で、一般2,500円。', '', '美術館', 'https://lp.p.pia.jp/article/news/515834/index.html',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('特別展「菅原道真」、2027年に東博・九博で', '没後1125年の節目に、道真ゆかりの社寺の国宝・重要文化財などの名宝を集める特別展。', '特別展「菅原道真」が、2027年夏から秋にかけて東京国立博物館と九州国立博物館で開催されることが発表された。没後1125年の節目に合わせた展覧会で、東京会場は東京国立博物館平成館で7月17日から9月12日まで、福岡会場は九州国立博物館3階特別展示室で10月9日から12月5日まで。道真ゆかりの社寺に伝わる国宝や重要文化財などの名宝を集め、その生涯と時代、人物像、後の天神信仰の広がりまでを紹介する。道真は6月25日に生まれ2月25日に没したとされ、全国の天満宮・天神社では25年ごとに大祭が営まれている。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261029-AEJ3030986/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('興福寺東金堂の「後堂」、12年ぶり特別公開', '創建1300年を記念し、11月1日から非公開エリアを公開。正了知大将立像を拝観できる。', '奈良・興福寺で、国宝・東金堂の非公開エリア「後堂」が11月1日から11月30日まで特別公開される。東金堂の創建1300年を記念したもので、後堂の公開は12年ぶり。後堂に安置される「正了知大将立像」は高さ約1.67メートルの寄せ木造りで、怒りの表情が特徴。1017年の火災の際に自ら飛び出して難を逃れたと伝わり、「踊り大将」とも呼ばれる。四天王立像や十二神将立像も、普段とは異なる横や後ろの角度から拝観できる。拝観時間は午前9時から午後5時まで(受付は午後4時45分まで)で、後堂を含む東金堂の拝観料は一般1,000円など。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261029-AEJ3030613/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('目［mé］《まさゆめ》、5年ぶりに代々木公園へ', '実在の人物の巨大な顔を空に浮かべる作品が、奥多摩で初開催、代々木公園では5年ぶりに登場。', '現代アートチーム・目［mé］の作品《まさゆめ》が、文化芸術祭「ARTE TOKYO」の特別企画として再び東京の空に浮かぶ。世界中から集めた実在する人物の顔から一人を選び、巨大な立体物として掲揚する作品で、メンバーの荒神明香が14歳のときに見た夢が着想源となっている。奥多摩町では初めての開催で、11月21日・22日に奥多摩総合運動公園で掲揚される。代々木公園では2021年以来5年ぶりとなり、12月5日・6日に中央広場に登場する。これまで2023年にリスボン、2024年にマドリードでも実施された。天候や風の影響で中止となる場合がある。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/exhibition/33237',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('国立国際美術館で特別展「コトバの重なる場所」', '言語や文化が交錯する「コンタクト・ゾーン」を切り口に、写真や映像でアジアを見つめる。', '大阪・中之島の国立国際美術館で、特別展「コトバの重なる場所」が2026年12月1日から2027年3月14日まで開催される。所蔵コレクションを活用した特別展で、言語や文化が交錯する「コンタクト・ゾーン」を切り口に、写真や映像作品を通じてアジアの諸地域を見つめる。植民地支配や戦争、国家間の対立による分断を経験し、言語や文化の接触から独特な歴史をたどった地域を取り上げる。出品作家は平敷兼七、下道基行、ツァオ・フェイ、山城知佳子、小泉明郎、イリヤ・カバコフ、今津景ら16組。会場はB3F展示室で、観覧料は一般1,800円。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33259',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('レウキッポスの娘たちの略奪', 'The Rape of the Daughters of Leucippus', 'ピーテル・パウル・ルーベンス', 'Peter Paul Rubens',
        1618,
        (select slug from public.art_movements where slug = 'baroque'),
        'アルテ・ピナコテーク', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Peter_Paul_Rubens_-_The_Rape_of_the_Daughters_of_Leucippus.jpg/960px-Peter_Paul_Rubens_-_The_Rape_of_the_Daughters_of_Leucippus.jpg', '1618年ごろにルーベンスが描いた、ギリシャ神話の一場面です。双子のカストルとポルックスが、レウキッポスの娘ポイベとヒラエイラを馬上へさらい上げようとしています。人と馬がからみ合い、画面全体が渦を巻くように動く構図に、ルーベンスの力強さがよく表れています。背景の風景は風景画家ヤン・ウィルデンスが描きました。ルネサンスの安定した構図を受け継ぎながら、それを大きな動きと豊かな肉体表現へ変えたところに、バロックの特徴が見えます。ミュンヘンのアルテ・ピナコテーク所蔵。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Peter_Paul_Rubens_-_The_Rape_of_the_Daughters_of_Leucippus.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('画家のアトリエ', 'The Painter''s Studio', 'ギュスターヴ・クールベ', 'Gustave Courbet',
        1855,
        (select slug from public.art_movements where slug = 'realism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Courbet_LAtelier_du_peintre.jpg/960px-Courbet_LAtelier_du_peintre.jpg', '縦約3.6メートル、横約6メートルの大作で、正式な題は「わが芸術的・道徳的生活の7年間を要約する現実的寓意」です。中央でクールベが故郷オルナンの風景を描き、その左には庶民の人々、右にはボードレールやプルードン、パトロンのブリュイアスら、彼を支えた人々が並びます。1855年のパリ万国博覧会で出品を拒まれたため、クールベは会場の近くに自ら「レアリスム館」を開いて展示しました。神話や歴史ではなく、自分の生きる社会を主題にした写実主義の宣言ともいえる作品です。パリのオルセー美術館所蔵。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Courbet_LAtelier_du_peintre.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('夏の日', 'Summer''s Day', 'ベルト・モリゾ', 'Berthe Morisot',
        1879,
        (select slug from public.art_movements where slug = 'impressionism'),
        'ナショナル・ギャラリー（ロンドン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Berthe_Morisot_-_Jour_d%27%C3%A9t%C3%A9%2C_1879.jpg/960px-Berthe_Morisot_-_Jour_d%27%C3%A9t%C3%A9%2C_1879.jpg', 'パリのブローニュの森の湖で、小舟に乗った二人の女性を描いた作品です。日傘や麦わら帽子、水面に浮かぶカモが、すばやく軽やかな筆づかいでとらえられています。1879年の第4回印象派展に「ブローニュの森の湖」という題で出品されました。マネやモネと同じく身近な余暇の場面を主題にしながら、女性の画家として女性たちの日常を間近から描いたところに、モリゾの持ち味があります。ロンドンのナショナル・ギャラリーとダブリンのヒュー・レーン美術館が共同で所蔵しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Berthe_Morisot_-_Jour_d''été,_1879.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('メレンコリアI', 'Melencolia I', 'アルブレヒト・デューラー', 'Albrecht Dürer',
        1514,
        (select slug from public.art_movements where slug = 'renaissance'),
        null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Albrecht_D%C3%BCrer_-_Melencolia_I_-_Google_Art_Project_%28427760%29.jpg/960px-Albrecht_D%C3%BCrer_-_Melencolia_I_-_Google_Art_Project_%28427760%29.jpg', '1514年に制作された銅版画で、「騎士と死と悪魔」「書斎の聖ヒエロニムス」とともにデューラーの三大銅版画（マイスターシュティッヒ）と呼ばれます。翼のある人物がコンパスを手にほおづえをつき、周りには多面体、砂時計、天秤、はしご、そして数字の和がどの列も34になる魔方陣が置かれています。魔方陣の下の段には制作年の1514が隠されています。イタリアで学んだ遠近法や幾何学を北方の緻密な線の技術と結びつけたデューラーらしく、知と憂鬱をめぐる謎の多い作品として今も解釈が続いています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Albrecht_Dürer_-_Melencolia_I_-_Google_Art_Project_(427760).jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジョン・コンスタブル', 'John Constable', 'コンスタブル',
        1776, 1837, 'west', array['romanticism']::text[],
        '故郷サフォークの田園と空を描き続けた、イギリスを代表する風景画家。', '1776年、イングランド東部サフォーク州のイースト・バーゴルトに生まれました。父は製粉所を持つ商人で、1799年にロンドンのロイヤル・アカデミー附属美術学校に入って絵を学びました。

ストアー川沿いやデダムの谷など、生まれ育った土地の田園風景を生涯の主題にしました。屋外で空や雲を観察し、天候や時刻を書きとめた雲のスケッチを数多く残しています。理想化された風景ではなく、目の前の自然の光や湿り気を描こうとしました。

代表作『乾草の車』は1824年のパリのサロンで金メダルを受け、ドラクロワらフランスの画家に影響を与えました。その影響は、のちのバルビゾン派や印象派にもつながったとされます。1837年にロンドンで亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A7%E3%83%B3%E3%83%BB%E3%82%B3%E3%83%B3%E3%82%B9%E3%82%BF%E3%83%96%E3%83%AB')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('狩野永徳', 'Kanō Eitoku', '永徳',
        1543, 1590, 'japan', array['kano']::text[],
        '織田信長・豊臣秀吉に仕え、桃山時代の豪壮な障壁画を描いた狩野派の絵師。', '1543年、狩野松栄の子、狩野元信の孫として生まれました。狩野派の絵師の中でも、最もよく知られる一人です。

織田信長や豊臣秀吉に重く用いられ、安土城、大坂城、聚楽第などの障壁画を手がけました。金地に巨木や獣を大きく描く豪壮な画風は、天下人の城や御殿にふさわしい新しい様式として、桃山時代の美術を代表するものになりました。一方で、細かく描き込んだ緻密な作品も残しています。

信長が上杉謙信に贈ったと伝わる『洛中洛外図屏風』、『唐獅子図屏風』『檜図屏風』、大徳寺聚光院の障壁画などが代表作です。城の障壁画の多くは失われました。1590年、東福寺法堂の天井画を制作中に亡くなりました。', 'https://ja.wikipedia.org/wiki/%E7%8B%A9%E9%87%8E%E6%B0%B8%E5%BE%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
